def main(folder: Path) -> None:
    for i, lang in enumerate(LANGS):
        data = {"@@locale": lang}
        for key, values in T.items():
            if len(values) != len(LANGS):
                raise SystemExit(f"{key} : {len(values)} traductions sur {len(LANGS)}")
            data[key] = values[i]
            if lang == LANGS[0] and key in PLACEHOLDERS:
                data[f"@{key}"] = {"placeholders": PLACEHOLDERS[key]}
        (folder / f"app_{lang}.arb").write_text(json.dumps(data, ensure_ascii=False, indent=2) + "\n", encoding="utf-8", newline="\n")
    print(f"{len(T)} textes, {len(LANGS)} langues")


if __name__ == "__main__":
    main(Path(sys.argv[1]))
